@startuml
class Kinepolis {}
class Cinema {
  +town: string
}
class Theatre {
  +theatreNumber: int
}
class Movie {}
class MovieCopy {}
class Show {
  +startTime: datetime
  +isPublished: boolean
}
class Reservation {
  +reservationTime: datetime
}
class Seat {
  +seatNumber: int
}
class Ticket {
  +isAnonymous: boolean
}
class CreditCard {}
class Offer {
  +expiryTime: datetime
}

Kinepolis "1" -- "*" Cinema : owns
Cinema "1" *-- "1..*" Theatre : has
Cinema "1" -- "*" MovieCopy : owns
Theatre "1" *-- "*" Show : hosts
Show "1" -- "1" Movie : features
Show "1" -- "*" MovieCopy : uses
Show "1" -- "*" Reservation : has
Show "1" -- "*" Ticket : has
Show "1" -- "0..1" Offer : provides
Reservation "1" -- "1" Seat : reserves
Reservation "1" -- "1" CreditCard : paid with
Ticket "1" -- "1" Seat : assigned
Ticket "1" -- "1" Show : for
Ticket "1" -- "1" CreditCard : paid with
@enduml

